package com.saleshub.web; import com.saleshub.service.SaleService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/sales") public class SaleController { private final SaleService service; public SaleController(SaleService s){service=s;} @PostMapping public ResponseEntity<?> create(@Valid @RequestBody SaleRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PostMapping("/{id}/cancel") public ResponseEntity<Void> cancel(@PathVariable Long id){service.cancel(id);return ResponseEntity.noContent().build();} }
